                Self.auditBaseline[Self.baselineKey(screen, issue)]
            }.map { "\(context): audit: \($0)" }
        let line = "SCREEN-SWEEP \(context): insets \(insets), \(found.count) finding(s)"
        print(line)
        add(XCTAttachment(string: ([line] + found).joined(separator: "\n")))
        return found
    }
}

