]

/// Every labelled leaf and control of the page (F5's rule), as drawn: each
/// frame clipped by its scrolling ancestors, so a chip scrolled out of the
/// instance bar (F5's fix) counts only for what shows. Dropped: scroll
/// bars, anything under 2 pt on either axis once clipped (visually hidden
/// text, or scrolled away), the same label at the same frame twice (a
/// field and its placeholder), and a same-label item inside another (a
/// control and its own icon button).
private func lookAtPage(_ app: XCUIApplication) throws -> PageLook {
    let web = app.webViews.firstMatch
    let frame = web.frame
    let controls: [XCUIElement.ElementType] = [.button, .link, .popUpButton, .menuButton,
                                               .textField, .textView, .searchField]
    var found: [(Chip, XCUIElement.ElementType)] = []
    func labelled(_ node: XCUIElementSnapshot) -> Bool {
        node.children.contains { !$0.label.isEmpty || labelled($0) }
    }
