                }
            } else {
                walk(child, clip: child.elementType == .scrollView ? clip.intersection(child.frame) : clip)
            }
        }
    }
    walk(try web.snapshot(), clip: frame)
    var kept: [(Chip, XCUIElement.ElementType)] = []
    for (chip, type) in found where !kept.contains(where: {
        $0.0.label == chip.label && ($0.0.frame.contains(chip.frame) || chip.frame.contains($0.0.frame))
    }) {
        kept.append((chip, type))
    }
    return PageLook(items: kept.map(\.0), web: frame,
                    types: kept.map { "\(describe([$0.0])) [\($0.1.rawValue)]" })
}

