// MARK: - F10 §4.5: the page's own content does not collide

/// F5's class, not F5's row: every labelled leaf and control the real
/// page has on screen, signed in and at rest, in portrait and landscape.
/// No two overlap as drawn (each inset by 1 pt, F5 §9's rule). Shown to
/// fail by removing the chip style's install: the sweep names F5's pair
/// without being pointed at the instance bar.
func testThePagesOwnContentDoesNotCollide() async throws {
    let run = try await signedInRun()
    var problems: [String] = []
    for (name, look) in [("portrait", run.portraitPage), ("landscape", run.landscapePage)] {
        guard let page = look else { problems.append("\(name): the page was not read"); continue }
        let line = "PAGE-SWEEP \(name): web=\(page.web) items=\(page.items.count)"
        print(line + " " + page.types.joined(separator: "; "))
        add(XCTAttachment(string: line + "\n" + page.types.joined(separator: "\n")))
        if page.items.count < 5 { problems.append("\(name): the sweep read too little of the page: \(line)") }
        for note in page.covered { print("PAGE-SWEEP \(name) not a collision: \(note)") }
        problems += page.collisions.map { "\(name): \($0)" }
    }
    // One assertion for all of them: this class stops at its first failure.
    XCTAssertTrue(problems.isEmpty, "F10 §4.5, the page's own content:\n" + problems.joined(separator: "\n"))
}

/// The page as the sweep sees it: its web view's frame, every item on
/// screen and its element type, and its overlapping pairs, judged while
/// the app was up: `collisions` both drawn, `covered` one of them hidden.
private struct PageLook {
    let items: [Chip]
    let web: CGRect
    let types: [String]
    let collisions: [String]
    let covered: [String]
}

/// Named by label, each with its reason: items the sweep reads that the
/// owner never sees where the accessibility tree puts them.
private static let pageSweepExempt: [String: String] = [
    "Skip to content": "a skip link: off screen until keyboard focus, drawn over the header only then",
]

/// Every labelled leaf and control of the page (F5's rule) that draws
/// something: a labelled `.other` is a region (a live region, a scroll
/// bar), not content. Each frame is clipped by its scrolling ancestors;
/// dropped are items under 2 pt on either axis once clipped (visually
/// hidden text, or scrolled away) and a same-label item at or inside
/// another's frame (a field and its placeholder, a control and its icon).
///
/// The tree has no z-order, so an overlap in it is not yet a collision:
/// content scrolled under the page's sticky header overlaps the header's
/// buttons there, as does a chip scrolled out of the instance bar under
/// the button beside it. A pair is a collision when both are hittable,
/// i.e. each is on top at its own centre: both drawn, one over the other.
private func lookAtPage(_ app: XCUIApplication) throws -> PageLook {
    let web = app.webViews.firstMatch
    let frame = web.frame
    let controls: [XCUIElement.ElementType] = [.button, .link, .popUpButton, .menuButton,
                                               .textField, .textView, .searchField]
    struct Item { let chip: Chip; let raw: CGRect; let type: XCUIElement.ElementType }
    var found: [Item] = []
    func labelled(_ node: XCUIElementSnapshot) -> Bool {
        node.children.contains { !$0.label.isEmpty || labelled($0) }
    }
    func walk(_ node: XCUIElementSnapshot, clip: CGRect) {
        for child in node.children {
            let leaf = controls.contains(child.elementType) || (!child.label.isEmpty && !labelled(child))
            if leaf {
                let shown = child.frame.intersection(clip)
                if !child.label.isEmpty, child.elementType != .other, Self.pageSweepExempt[child.label] == nil,
                   !shown.isNull, shown.width >= 2, shown.height >= 2 {
                    found.append(Item(chip: Chip(label: child.label, frame: shown), raw: child.frame,
                                      type: child.elementType))
                }
            } else {
                walk(child, clip: child.elementType == .scrollView ? clip.intersection(child.frame) : clip)
            }
        }
    }
    walk(try web.snapshot(), clip: frame)
    try? XCUIScreen.main.screenshot().pngRepresentation.write(to: URL(fileURLWithPath: // F10-DIAG
        "/Users/olof/src/latchkey-f10/app/build/f10-shots/page-\(frame.width > frame.height ? "landscape" : "portrait").png"))
    var kept: [Item] = []
    for item in found where !kept.contains(where: {
        $0.chip.label == item.chip.label && ($0.chip.frame.contains(item.chip.frame) || item.chip.frame.contains($0.chip.frame))
    }) {
        kept.append(item)
    }

    func hittable(_ item: Item) -> Bool {
        web.descendants(matching: item.type).matching(NSPredicate(format: "label == %@", item.chip.label))
            .allElementsBoundByIndex.first { $0.frame == item.raw }?.isHittable ?? false
    }
    var collisions: [String] = [], covered: [String] = []
    for (i, a) in kept.enumerated() {
        for b in kept[(i + 1)...]
        where !a.chip.frame.insetBy(dx: 1, dy: 1).intersection(b.chip.frame.insetBy(dx: 1, dy: 1)).isEmpty {
            let (ha, hb) = (hittable(a), hittable(b))
            let pair = "\(describe([a.chip])) [\(ha ? "on top" : "hidden")] and \(describe([b.chip])) [\(hb ? "on top" : "hidden")]"
            if ha && hb { collisions.append(pair + " overlap") } else { covered.append(pair) }
        }
    }
    return PageLook(items: kept.map(\.chip), web: frame,
                    types: kept.map { "\(describe([$0.chip])) [\($0.type.rawValue)]" },
                    collisions: collisions, covered: covered)
}

// MARK: - F14: one signed-in run, read by the tests that only look at it

/// Everything four tests looked at after the same launch and the same CLI
/// sign-in, none of them changing the session: the sign-in's own traces,
/// the instance bar in portrait and in landscape, the sessions panel back
/// in portrait, and Status. Taken once (F14), in an order in which no
/// step disturbs what a later one reads; each test still asserts its own
/// claim under its own name, and a test run on its own takes its own.
///
/// Sign-in and Status are `testPastingCLIOutputSignsIn`'s claims, and the
/// first test by name takes the run, so their own assertions stay where
/// they are. Everything else is recorded without failing, so a broken
/// chip row fails only the chip tests. Cached only once signed in.
private struct BarLook {
    let chips: [Chip]

